import {scheduleForm,bindSchedule,readSchedule} from './sync-schedule.js';
import {readIntegrations,saveIntegrations} from './integration-store.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,id,primary=false)=>`<button id="${id}" class="button ${primary?'primary':''}">${text}</button>`;
function dialog(id,title,body,action){return `<dialog id="${id}"><div class="dialog-head"><h2>${title}</h2><button class="button link" data-close>閉じる</button></div><div class="dialog-body">${body}</div><div class="dialog-foot"><button class="button" data-close>キャンセル</button>${action}</div></dialog>`}
const sources=[{label:'ICD10コードマスタ',fields:['Id','ICD10コード','傷病名','特定疾病','特定部位'],target:'傷病名マスタ'},{label:'医療機関マスタ',fields:['Id','機関コード','医療機関名','都道府県'],target:'医療機関マスタ'},{label:'TNM分類マスタ',fields:['Id','分類コード','分類名'],target:'TNM分類マスタ'}];
function drawMapping(index,job=null){const src=sources[index];$('record-key').innerHTML=src.fields.map(f=>`<option ${f===(job?.key||'Id')?'selected':''}>${esc(f)}</option>`).join('');$('mapping').innerHTML=src.fields.map(f=>{const n=job?.fields.indexOf(f);return `<tr><td><input type="checkbox" data-field value="${esc(f)}" ${!job||n>=0?'checked':''} aria-label="${esc(f)}を同期"></td><td>${esc(f)}</td><td><input type="text" data-target="${esc(f)}" aria-label="${esc(f)}の出力列名" value="${esc(job&&n>=0?job.names[n]:f)}"></td></tr>`}).join('')}

export function openMasterSync(masterName,onSaved){
const store=readIntegrations(),job=store.jobs[masterName];
$('sync-dialog')?.remove();document.body.insertAdjacentHTML('beforeend',dialog('sync-dialog','データ同期',`<div class="sync-control-bar"><label class="switch-label"><input id="sync-enabled" type="checkbox" role="switch"><span id="sync-enabled-label">有効</span></label></div><div class="api-grid"><div class="field"><label for="sync-connection">接続</label><select id="sync-connection">${store.connections.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="source-object">取得元データ</label><select id="source-object">${sources.map((s,i)=>`<option value="${i}">${esc(s.label)}</option>`).join('')}</select></div><div class="field"><label for="record-key">レコードID列</label><select id="record-key"></select></div><div class="field"><label for="target-master">同期先マスタ</label><input id="target-master" type="text" readonly value="${esc(masterName)}"></div></div><div class="auto-update-line"><label class="switch-label"><input id="sync-auto" type="checkbox" role="switch">自動更新</label></div><div id="master-schedule">${scheduleForm()}</div><div class="api-mapping"><h2>フィールド対応</h2><table class="api-map"><thead><tr><th>同期</th><th>取得元フィールド</th><th>マスタの列名</th></tr></thead><tbody id="mapping"></tbody></table></div><p class="api-note">選択した周期・時刻に実行します（日本時間）。全量取得し、未変更データは再構築しません。</p><p id="sync-error" class="status error" role="alert"></p>`,button('保存','save-sync',true)));
const d=$('sync-dialog');d.querySelectorAll('.api-note').forEach(e=>e.remove());d.querySelectorAll('[data-close]').forEach(e=>e.onclick=()=>d.close());
$('sync-connection').value=job?.connection||store.connections[0]?.id||'';$('source-object').value=job?.source||0;$('record-key').value=job?.key||'Id';
drawMapping(job?.source||0,job);
$('sync-enabled').checked=job?.enabled??true;$('sync-auto').checked=job?.automatic??true;bindSchedule(job?.schedule||store.schedule,()=>{});const refreshControls=()=>{$('sync-enabled-label').textContent=$('sync-enabled').checked?'有効':'一時停止';$('master-schedule').hidden=!$('sync-auto').checked};$('sync-enabled').onchange=refreshControls;$('sync-auto').onchange=refreshControls;refreshControls();d.querySelectorAll('.api-note').forEach(e=>e.remove());
$('source-object').onchange=()=>drawMapping(Number($('source-object').value));
$('save-sync').onclick=()=>{const fields=Array.from(d.querySelectorAll('[data-field]:checked')).map(e=>e.value),names=fields.map(f=>d.querySelector('[data-target="'+f+'"]').value.trim()),key=$('record-key').value;
if($('sync-auto').checked&&!$('sync-time').checkValidity()){$('sync-time').reportValidity();return}
if(!$('sync-connection').value){$('sync-error').textContent='API設定で接続を追加してください。';return}
if(!fields.length||!fields.includes(key)||names.some(n=>!n)||new Set(names).size!==names.length){$('sync-error').textContent='ID列を同期対象に含め、空欄・重複のない出力列名を指定してください。';return}
const latest=readIntegrations();if(!latest.connections.some(c=>c.id===$('sync-connection').value)){$('sync-error').textContent='接続が削除されました。再度選択してください。';return}
latest.jobs[masterName]={connection:$('sync-connection').value,source:Number($('source-object').value),target:masterName,key,fields,names,enabled:$('sync-enabled').checked,automatic:$('sync-auto').checked,schedule:readSchedule()};
saveIntegrations(latest);d.close();onSaved?.();};d.showModal();}
